const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Thailand geometry
  const thailand = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Thailand'))
    .geometry();

  // 2. Load MODIS LST data
  const modisLST = ee.ImageCollection('MODIS/006/MOD11A2')
    .select('LST_Day_1km');

  // Function to convert Kelvin to Celsius and apply QC
  function processLST(image) {
    const lst = image.select('LST_Day_1km')
      .multiply(0.02)  // Scale factor
      .subtract(273.15);  // Convert K to C
    return lst.copyProperties(image, ['system:time_start']);
  }

  // 3. Get baseline period (April 2001-2010)
  const baseline = modisLST
    .filter(ee.Filter.calendarRange(2001, 2010, 'year'))
    .filter(ee.Filter.calendarRange(4, 4, 'month'))
    .map(processLST);

  const baselineSize = baseline.size().getInfo();
  console.log('Baseline images (April 2001-2010):', baselineSize);

  if (baselineSize === 0) {
    console.log('No baseline data found');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get April 2016 data
  const april2016 = modisLST
    .filter(ee.Filter.date('2016-04-01', '2016-05-01'))
    .map(processLST);

  const april2016Size = april2016.size().getInfo();
  console.log('April 2016 images:', april2016Size);

  if (april2016Size === 0) {
    console.log('No April 2016 data found');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Calculate mean LST for both periods
  const baselineMean = baseline.mean();
  const april2016Mean = april2016.mean();

  // 6. Reduce regions with pixel count validation
  const reductionParams = {
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: thailand,
    scale: 3000,
    maxPixels: 1e9
  };

  const baselineStats = baselineMean.reduceRegion(reductionParams).getInfo();
  const april2016Stats = april2016Mean.reduceRegion(reductionParams).getInfo();

  const baselineLST = baselineStats.LST_Day_1km_mean;
  const baselineCount = baselineStats.LST_Day_1km_count;
  const april2016LST = april2016Stats.LST_Day_1km_mean;
  const april2016Count = april2016Stats.LST_Day_1km_count;

  console.log('Baseline LST (°C):', baselineLST ? baselineLST.toFixed(2) : 'null');
  console.log('Baseline valid pixels:', baselineCount);
  console.log('April 2016 LST (°C):', april2016LST ? april2016LST.toFixed(2) : 'null');
  console.log('April 2016 valid pixels:', april2016Count);

  // 7. Validation checks
  if (baselineCount === 0 || april2016Count === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (baselineLST === null || april2016LST === null || 
      isNaN(baselineLST) || isNaN(april2016LST) ||
      baselineLST < -50 || baselineLST > 70 ||
      april2016LST < -50 || april2016LST > 70) {
    console.log('Invalid LST values detected');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Compare and determine answer
  const difference = april2016LST - baselineLST;
  console.log('Temperature difference (°C):', difference.toFixed(2));

  if (april2016LST > baselineLST) {
    console.log('April 2016 LST is higher than 2001-2010 baseline');
    console.log('<answer>A</answer>');
  } else {
    console.log('April 2016 LST is not higher than 2001-2010 baseline');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
